implementation:
#include <linux/errno.h>
#include <linux/slab.h>
#include <linux/hmac.h>
#include <linux/crypto.h>

enum integrity_status {
    INTEGRITY_PASS = 0,
    INTEGRITY_FAIL = 1,
    INTEGRITY_NO_ATTRIBUTE = 2
}; 

enum integrity_status verify_hmac_xattr(struct dentry *dentry, const char *xattr_name, char *xattr_value, size_t xattr_value_len, struct integrity_iint_cache *iint) {
    enum integrity_status status = INTEGRITY_PASS;

    /* Check cached integrity status first */
    if (iint->status != INTEGRITY_PASS) {
        return iint->status;
    }

    if (!xattr_name || !xattr_value || xattr_value_len == 0) {
        return INTEGRITY_NO_ATTRIBUTE;
    }

    /* Allocate memory for HMAC calculation */
    void *digest = kmalloc(xattr_value_len, GFP_KERNEL);
    if (!digest) {
        return INTEGRITY_FAIL;
    }

    /* Calculate HMAC or hash based on the type of extended attribute */
    struct crypto_shash *tfm = crypto_alloc_shash("hmac(sha256)", 0, 0);
    if (IS_ERR(tfm)) {
        kfree(digest);
        return INTEGRITY_FAIL;
    }

    struct shash_desc *desc = kmalloc(sizeof(*desc) + crypto_shash_descsize(tfm), GFP_KERNEL);
    if (!desc) {
        crypto_free_shash(tfm);
        kfree(digest);
        return INTEGRITY_FAIL;
    }

    desc->tfm = tfm;

    int err = crypto_shash_init(desc);
    if (err) {
        kfree(desc);
        crypto_free_shash(tfm);
        kfree(digest);
        return INTEGRITY_FAIL;
    }

    err = crypto_shash_update(desc, xattr_value, xattr_value_len);
    if (err) {
        kfree(desc);
        crypto_free_shash(tfm);
        kfree(digest);
        return INTEGRITY_FAIL;
    }

    err = crypto_shash_final(desc, digest);
    if (err) {
        kfree(desc);
        crypto_free_shash(tfm);
        kfree(digest);
        return INTEGRITY_FAIL;
    }

    /* Compare calculated digest with stored digest in extended attribute */
    if (memcmp(digest, xattr_value, xattr_value_len) != 0) {
        status = INTEGRITY_FAIL;
    }

    kfree(desc);
    crypto_free_shash(tfm);
    kfree(digest);

    iint->status = status;

    return status;
}
